  const el = document.createElement("div"); el.className = "aich"; box.append(el); try { speechSynthesis.cancel(); } catch(e){}
  const close = () => { try { speechSynthesis.cancel(); } catch(e){} el.remove(); };
  const S0 = {msgs: [], turns: 0, mine: [], phrases: [], busy: false, over: false};
