function close(){ try { speechSynthesis.cancel(); if (AU) AU.pause(); } catch(e){} if (root){ root.remove(); root = null; } document.body.classList.remove("dp-open"); try { window.dispatchEvent(new Event("hashchange")); } catch(e){} }
// 别人说的一句：只能听（蓝）
const avOf = n => { try { const H = window.HVI; if (H && H.npcAv) return H.npcAv(Object.assign({id: n}, (H.npc && H.npc(n)) || {}), 42); } catch(e){} return npc(n)[1]; };
const hlIt = (en, hl) => { let h = esc(en); (hl || []).forEach(w => { h = h.replace(new RegExp("(" + w.replace(/[.*+?^${}()|[\]\\]/g, "\\$&") + ")", "i"), "<i>$1</i>"); }); return h; };
const bubble = (n, en, zh, hl, fold) => { const N = npc(n);
  return '<div class="who' + (fold ? " fold" : "") + '"><span class="av">' + avOf(n) + '</span><div class="bub"><b>' + esc(N[0]) + (N[2] ? ' · ' + esc(N[2]) : "") + ' · 🎭</b>' + hlIt(en, hl) + '<small>' + esc(zh) + '</small></div><button class="hear" data-say="' + esc(en) + '" aria-label="听">🔊</button></div>'; };
const wireSay = () => $$("[data-say]").forEach(b => b.onclick = () => say(b.dataset.say));
const stepsH = n => { const L = n === 3 ? STEPS4 : STEPS5; return '<div class="steps">' + L.map((x, i) => '<div class="' + (i < ph ? "d" : i === ph ? "now" + (/^🎤/.test(x) ? " s" : "") : "") + '">' + x + '</div>').join("") + '</div>'; };
const next = (note, btn, cls, dis) => '<div class="next"><span class="n">' + (note || "") + '</span><button class="big ' + (cls || "") + '" id="dpNx"' + (dis ? " disabled" : "") + '>' + btn + '</button></div>';
// ───── 顶上：哪座岛 › 哪个话题 · 四层 ─────
function bar(){ const s = ST(key), nx = level(s), H = window.HVI;
  let isn = ""; try { isn = H && H.isleNm ? H.isleNm(isle) : ""; } catch(e){}
  $("#dpCr").innerHTML = esc(isn ? isn + " › " : "") + esc(title) + ' ›<b>' + esc(D.title[2]) + '</b>';
  $("#dpCh").innerHTML = LV.map((x, i) => (i ? '<span class="ln"></span>' : "") + '<button data-lv="' + i + '" class="' + (i === cur ? "now" : sealed(s, i) ? "d" : "") + '"' + (i > nx ? " disabled" : "") + '><i>' + (sealed(s, i) && i !== cur ? "✓" : i + 1) + '</i>' + x[0] + '</button>').join("");
  $$("[data-lv]").forEach(b => b.onclick = () => { const i = +b.dataset.lv; if (i > level(ST(key))) return; go(i); }); }
// ───── 左页：你的故事（只有你自己的话）+ 这个故事里你抓到的词 ─────
// pv = 正在拼的这一层的句子（还没盖章，跟着你点的选项变）
