// ───── 🎤 说：跟着说 → 只看中文（每句两遍），最后整段 ─────
const RUNG = [["① 跟着说", "先听，看着整句说"], ["② 只看中文", "英文藏起来，自己说"], ["③ 整段说", "连起来一口气说"]];
function drill(L, n, onDone){ const box = $("#dpR"), st = {i: 0, r: 0};
  const s0 = ST(key); if (L.length && L.every(l => (s0.said || {})[l[0]])) st.i = L.length;   // 都说熟过了：直接整段
  if (!L.length){ onDone && onDone(); return; }
  const draw = heard => { const whole = st.i >= L.length, l = L[Math.min(st.i, L.length - 1)], r = whole ? 2 : st.r;
    box.innerHTML = stepsH(n) + '<span class="tg s">🎤 说你的' + (whole ? " · 整段" : " · 第 " + (st.i + 1) + " / " + L.length + " 句") + '</span>' +
      '<div class="ladder">' + RUNG.map((x, k) => '<div class="rung' + (k < r ? " d" : k === r ? " now" : "") + '"><b>' + x[0] + (k < r ? " ✓" : "") + '</b>' + x[1] + '</div>').join("") + '</div>' +
      '<div class="stage">' + (whole ? '<div class="zh big">' + esc(L.map(x => x[1]).join("")) + '</div>' + (st.peek ? '<div class="en long">' + esc(L.map(x => x[0]).join(" ")) + '</div>' : "")
        : '<div class="zh' + (r === 1 ? " big" : "") + '">' + esc(l[1]) + '</div>' + (r === 0 || heard != null || st.peek ? '<div class="en">' + enH(l[0], heard) + '</div>' : "")) +
      '<button class="mic" id="dpMic" aria-label="说">🎤</button><div class="live" id="dpLv"></div><div class="mh">点一下说，说完停一下会自己停</div>' +
      (whole ? "" : '<div class="reps">' + [0, 1].map(k => '<i class="' + (k < r ? "d" : "") + '"></i>').join("") + '</div>') +
      '<div class="sm"><button class="lnk" id="dpHr">🔊 再听一遍</button>' + (r > 0 && !st.peek ? '<button class="lnk" id="dpPk">偷看一眼</button>' : "") + '<button class="lnk" id="dpSk">跳过 ›</button></div></div>' +
      (whole ? "" : '<div class="queue">' + L.map((x, k) => '<div class="qi' + (k < st.i ? " d" : k === st.i ? " now" : "") + '"><span class="ck">' + (k < st.i ? "✓" : k + 1) + '</span>' + esc(x[0]) + '</div>').join("") + '</div>');
    const adv = () => { st.peek = 0; if (whole){ onDone && onDone(); return; } if (st.r < 1) st.r++; else { upd(x => { (x.said || (x.said = {}))[l[0]] = 1; }); st.i++; st.r = 0; left(); } draw(); if (!(st.i >= L.length) && st.r === 0) say(L[st.i][0]); };
    $("#dpHr").onclick = () => say(whole ? L.map(x => x[0]).join(" ") : l[0]);
    const pk = $("#dpPk"); if (pk) pk.onclick = () => { st.peek = 1; draw(); };
    $("#dpSk").onclick = adv;
    const mic = $("#dpMic"); mic.onclick = () => { if (mic.classList.contains("on")) return; mic.classList.add("on"); try { speechSynthesis.cancel(); if (AU) AU.pause(); } catch(e){}
      listen($("#dpLv"), t => { mic.classList.remove("on"); ding(); draw(t || ""); const lv = $("#dpLv"); if (lv) lv.innerHTML = t ? "🗣️ " + esc(t) : "✓ 说了"; setTimeout(() => { if (root && $("#dpMic")) adv(); }, t ? 1300 : 700); }, whole ? null : key + "|" + l[0], whole); };
  };
  draw(); if (st.i < L.length) say(L[0][0]); }
// ───── 盖章：存下来，别人回你一句，左页这一层亮 ─────
