  try { localStorage.setItem("hv.me.home", s.start); if (window.hvSyncMark) window.hvSyncMark("hv.me.home"); } catch(e){}
  W = {}; ph = n === 3 ? 3 : 5; const nx = level(ST(key)); bar(); left();
  $("#dpR").innerHTML = stepsH(n) + '<div class="seal"><div class="stamp">' + LV[n][0] + '<small>SAID · ' + today().slice(5).replace("-", ".") + '</small></div>' +
    '<div class="q" style="justify-content:center;margin-top:16px">第 ' + (n + 1) + ' 层说完了</div>' + (R ? bubble(R[0], R[1], R[2]) : "") + (extra || "") +
    '<div class="sm" style="margin-top:18px;gap:10px">' + (nx < 4 ? '<button class="big say" id="dpGo">接着第 ' + (nx + 1) + ' 层：' + LV[nx][0] + ' →</button>' : '<button class="big say" id="dpGo">✨ 听听你的一分钟</button>') + '<button class="big lt" id="dpBye">今天先到这儿</button></div>' +
    '<div class="qz" style="margin-top:14px">这一层的句子和词进了「我的船」，1 天、3 天、7 天后叫你再说一遍。</div></div>';
